#!/usr/bin/env python3
"""Reviewed fixed-target candidate; activation is a separate explicit operation."""
import ast,base64,datetime,fcntl,hashlib,json,os,pathlib,stat,subprocess,sys,tempfile
P=pathlib.Path
ROOT=P('/mnt/data/docker')
CATALOG=P('/usr/local/lib/raspberry-mcp/project-catalog.json')
TX=P('/var/lib/raspberry-icloud-owner-repair-v1')
IMAGE='sha256:130241f28d01fa80dfa3b44f7d89781c188d8642ecab9024f079f19f9f82baa0'
EXPECTED={'homeassistant/custom_components/icloud/__init__.py': '0d4935930a4a744d50d2b7f8c8168c813ac84043de67c8ee01aeb61ab1117a08', 'homeassistant/custom_components/icloud/device_owner.py': None, 'homeassistant/custom_components/icloud/upstream.json': '05dc47a109da4c7f731728a71ef70122eade753c75e763b1931d1568623cff7d', 'homeassistant/tests/test_icloud_device_owner.py': None, 'homeassistant/tests/icloud_native_fixture.py': None, '@mcp-project-catalog.json': '6c965958fe69192af203ed99f492455678420ed7176d2057880459516dba0bb9'}
DEPENDENCIES={'homeassistant/custom_components/icloud/manual_auth.py': 'c5469affcb15d096411f951739bacf7110a0b19c99b9f1c0bd966a6dab5662c5', 'homeassistant/custom_components/icloud/setup_retry.py': '5611e06df27d1477983f49e579fd163955eb0a4adde4fb0c7e750058f9e58270', 'homeassistant/custom_components/icloud/config_flow.py': 'b3c6ebc9c13d8ae9b8efadb73acb3db1e1e338cf14151377f9f5821498f61d8e', 'homeassistant/custom_components/icloud/LICENSE.upstream': 'c71d239df91726fc519c6eb72d318ec65820627232b2f796219e87dcf35d0ab4', 'homeassistant/tests/test_icloud_manual_auth.py': 'c632f7f6a5385f59fe3fa2497b5ad79647b99c5e8a8a14f6f6c861b740e261c3'}
PAYLOAD={'homeassistant/custom_components/icloud/__init__.py': '', 'homeassistant/custom_components/icloud/device_owner.py': '', 'homeassistant/custom_components/icloud/upstream.json': '', 'homeassistant/tests/test_icloud_device_owner.py': '', 'homeassistant/tests/icloud_native_fixture.py': '', '@mcp-project-catalog.json': ''}
def sha(data):return hashlib.sha256(data).hexdigest()
def target(name):return CATALOG if name=='@mcp-project-catalog.json' else ROOT/name
def safe(path):
    for parent in [path,*path.parents]:
        if parent.is_symlink():raise RuntimeError('symlink_rejected')
def current(path):
    safe(path)
    if not path.exists():return None
    if not path.is_file():raise RuntimeError('non_regular_file')
    return sha(path.read_bytes())
def command(*args):return subprocess.run(args,check=True,capture_output=True,text=True,timeout=90).stdout.strip()
def container_state():
    result=json.loads(command('docker','inspect','--format','{"image":{{json .Image}},"running":{{json .State.Running}},"started_at":{{json .State.StartedAt}}}', 'homeassistant'))
    if result['image']!=IMAGE:raise RuntimeError('runtime_image_changed')
    return result
def replacement(path,data,uid,gid,mode=0o644):
    safe(path);fd,temp=tempfile.mkstemp(prefix='.icloud-owner-',dir=path.parent)
    try:
        with os.fdopen(fd,'wb') as f:
            os.fchmod(f.fileno(),mode);os.fchown(f.fileno(),uid,gid);f.write(data);f.flush();os.fsync(f.fileno())
        os.replace(temp,path)
        dfd=os.open(path.parent,os.O_RDONLY|os.O_DIRECTORY)
        try:os.fsync(dfd)
        finally:os.close(dfd)
    finally:
        if os.path.exists(temp):os.unlink(temp)
def save(row):
    row['updated_at']=datetime.datetime.now(datetime.timezone.utc).isoformat()
    row.setdefault('created_at',row['updated_at'])
    replacement(TX/'operation.json',(json.dumps(row,sort_keys=True)+'\n').encode(),0,0,0o600)
def load():return json.loads((TX/'operation.json').read_text())
def payloads():return {name:base64.b64decode(data) for name,data in PAYLOAD.items()}
def validate_code():
    for name,data in payloads().items():
        if name.endswith('.py'):ast.parse(data,filename=name)
        if name.endswith('.json'):json.loads(data)
def preflight():
    validate_code()
    for name,digest in DEPENDENCIES.items():
        if current(ROOT/name)!=digest:raise RuntimeError('dependency_changed')
    for name,digest in EXPECTED.items():
        if current(target(name))!=digest:raise RuntimeError('source_changed')
    state=container_state()
    if not state['running']:raise RuntimeError('homeassistant_not_running')
    # Verify the persistent mount using only the approved destination projection.
    source=command('docker','inspect','--format','{{range .Mounts}}{{if eq .Destination "/config"}}{{.Source}}{{end}}{{end}}','homeassistant')
    if source!=str(ROOT/'homeassistant'):raise RuntimeError('config_mount_changed')
    return state
def verify_sources():
    validate_code()
    for name,data in payloads().items():
        if current(target(name))!=sha(data):raise RuntimeError('installed_source_changed')
    for name,digest in DEPENDENCIES.items():
        if current(ROOT/name)!=digest:raise RuntimeError('dependency_changed')
def restore(row):
    data=payloads()
    # Precheck every target before changing any, then repeat each CAS at write time.
    for name in row['written']:
        if current(target(name))!=sha(data[name]):raise RuntimeError('rollback_conflict')
    for name in reversed(row['written']):
        path=target(name)
        if current(path)!=sha(data[name]):raise RuntimeError('rollback_conflict')
        meta=row['original'][name]
        if meta['sha256'] is None:path.unlink()
        else:
            raw=(TX/meta['backup']).read_bytes()
            if sha(raw)!=meta['sha256']:raise RuntimeError('backup_changed')
            replacement(path,raw,meta['uid'],meta['gid'],meta['mode'])
    row['phase']='source_restored';save(row)
def apply():
    state=preflight()
    if TX.exists():raise RuntimeError('existing_operation_reconcile_first')
    TX.mkdir(mode=0o700)
    row={'operation_id':'icloud-owner-repair-v1','phase':'preparing','original':{},'written':[],'activation_attempted':False,'before_started_at':state['started_at']}
    save(row)
    for index,name in enumerate(payloads()):
        path=target(name);meta={'sha256':EXPECTED[name]}
        if EXPECTED[name] is not None:
            st=path.stat();raw=path.read_bytes()
            if sha(raw)!=EXPECTED[name]:raise RuntimeError('source_changed')
            meta.update(uid=st.st_uid,gid=st.st_gid,mode=stat.S_IMODE(st.st_mode),backup=str(index)+'.backup')
            replacement(TX/meta['backup'],raw,0,0,0o600)
        else:
            st=path.parent.stat();meta.update(uid=st.st_uid,gid=st.st_gid,mode=0o644)
        row['original'][name]=meta
    save(row)
    try:
        for name,data in payloads().items():
            path=target(name)
            if current(path)!=EXPECTED[name]:raise RuntimeError('source_changed')
            meta=row['original'][name]
            # Record intent before replace; interrupted operations require reconciliation.
            row['phase']='applying';row['intent']=name;save(row)
            replacement(path,data,meta['uid'],meta['gid'],meta['mode']);row['written'].append(name);save(row)
        verify_sources();row['phase']='source_applied_not_loaded';row.pop('intent',None);save(row)
    except BaseException:
        restore(row);raise
    return row
def activate():
    row=load()
    if row['phase']!='source_applied_not_loaded':raise RuntimeError('reconcile_before_activation')
    verify_sources();before=container_state()
    if not before['running']:raise RuntimeError('homeassistant_not_running')
    row.update(phase='activation_outcome_unknown',activation_attempted=True,before_started_at=before['started_at']);save(row)
    command('docker','restart','--time','30','homeassistant')
    return reconcile()
def reconcile():
    row=load()
    if row['phase'] in ('source_applied_not_loaded','activated_pending_functional_validation'):verify_sources()
    if row['phase']=='activation_outcome_unknown':
        verify_sources();state=container_state()
        if state['running'] and state['started_at']!=row['before_started_at']:
            row.update(phase='activated_pending_functional_validation',after_started_at=state['started_at']);save(row)
    return row
def rollback():
    row=load()
    if row['phase'] not in ('source_applied_not_loaded','activation_outcome_unknown','activated_pending_functional_validation'):raise RuntimeError('manual_reconciliation_required')
    container_state();restore(row)
    if row['activation_attempted']:
        row['phase']='rollback_restart_outcome_unknown';save(row)
        command('docker','restart','--time','30','homeassistant')
        row['phase']='rollback_pending_functional_validation';save(row)
    return row
def main():
    if sys.argv[1:] not in ([x] for x in ('--check','--apply','--activate','--verify','--rollback','--status')):raise RuntimeError('explicit_mode_required')
    mode=sys.argv[1]
    if mode=='--check':preflight();print('iCloud repair preflight passed; no changes made.');return
    if os.geteuid()!=0:raise RuntimeError('sudo_required')
    safe(TX)
    # Persistent lock outside the transaction allows serialization of first creation.
    fd=os.open(str(TX)+'.lock',os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW,0o600)
    try:
        fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
        row={'--apply':apply,'--activate':activate,'--verify':reconcile,'--rollback':rollback,'--status':load}[mode]()
        print(json.dumps({k:v for k,v in row.items() if k in ('operation_id','phase','before_started_at','after_started_at','activation_attempted','updated_at','created_at')}))
    finally:os.close(fd)
if __name__=='__main__':
    try:main()
    except Exception as error:
        category=str(error) if isinstance(error,RuntimeError) and str(error).replace('_','').isalnum() else type(error).__name__
        raise SystemExit('iCloud repair stopped: '+category+'; reconcile before retry.')
